fn resolve_report_dates(
    since: Option<String>,
    until: Option<String>,
) -> ResultWithDefaultError<(String, String)> {
    let today = Local::now().date_naive();

    let since_resolved = match since {
        Some(s) => resolve_report_date(&s)?,
